//
// CPU emulation of the opt-in half WMMA quantized prefill (`prefill.precision = "half"`).
//
// The CUDA source generated by `boring build --target cuda` is compiled as ordinary C++
// against a small fake CUDA runtime: every GPU thread is a real `std::thread`,
// `__syncthreads` is a real barrier, `__shared__` is `static`, `__half` values are
// rounded to IEEE half precision, and `nvcuda::wmma` fragments are plain 16x16 arrays
// (each thread of a warp redundantly computes its warp's result, which is harmless).
// The kernel's output is compared with a CPU reference that applies the same half
// rounding to activations and dequantized weights.
//
// This validates the tile staging, K-stage loop, fragment-to-output mapping, edge
// guards and bias, not real tensor-core fragment layouts or GPU memory ordering.
//
//   cargo test --test cuda_half_prefill_emulation

use std::fs;
use std::path::PathBuf;
use std::process::Command;

const FAKE_CUDA_RUNTIME: &str = r#"
#pragma once
#include <cstdint>
#include <cmath>
#include <condition_variable>
#include <mutex>
struct BoringDim3 { unsigned x = 0, y = 0, z = 0; };
inline thread_local BoringDim3 threadIdx;
inline BoringDim3 blockIdx, blockDim, gridDim;
#define __global__
#define __device__
#define __shared__ static
#define __align__(n) __attribute__((aligned(n)))
static const int warpSize = 32;
template <class T> inline T __shfl_sync(unsigned, T v, int) { return v; }
template <class T> inline T __shfl_xor_sync(unsigned, T v, int) { return v; }
struct BoringBarrier {
    std::mutex m; std::condition_variable cv; int count = 0, waiting = 0, generation = 0;
    void wait() {
        std::unique_lock<std::mutex> lock(m);
        int gen = generation;
        if (++waiting == count) { waiting = 0; ++generation; cv.notify_all(); }
        else cv.wait(lock, [&] { return gen != generation; });
    }
};
inline BoringBarrier boring_barrier;
inline void __syncthreads() { boring_barrier.wait(); }
// IEEE half rounding (round to nearest even), kept as a float.
typedef float __half;
inline float __float2half(float v) {
    if (v == 0.0f || std::isnan(v) || std::isinf(v)) return v;
    float a = std::fabs(v), r;
    if (a >= 65520.0f) return std::copysign(INFINITY, v);
    if (a < 6.103515625e-05f) r = std::nearbyint(std::ldexp(a, 24)) / 16777216.0f;
    else { int e; float m = std::frexp(a, &e); r = std::ldexp(std::nearbyint(std::ldexp(m, 11)), e - 11); }
    return std::copysign(r, v);
}
"#;

const FAKE_MMA: &str = r#"
#pragma once
namespace nvcuda { namespace wmma {
struct matrix_a {}; struct matrix_b {}; struct accumulator {};
struct row_major {}; struct col_major {};
enum layout_t { mem_row_major, mem_col_major };
template <class U, int M, int N, int K, class T = float, class L = void>
struct fragment { float v[16][16]; };
template <int M, int N, int K, class T, class L>
void load_matrix_sync(fragment<matrix_a, M, N, K, T, L>& f, const float* p, unsigned ld) {
    for (int i = 0; i < 16; ++i) for (int k = 0; k < 16; ++k) f.v[i][k] = p[i * ld + k];
}
template <int M, int N, int K, class T, class L>
void load_matrix_sync(fragment<matrix_b, M, N, K, T, L>& f, const float* p, unsigned ld) {
    for (int k = 0; k < 16; ++k) for (int j = 0; j < 16; ++j) f.v[k][j] = p[k * ld + j];
}
template <int M, int N, int K>
void fill_fragment(fragment<accumulator, M, N, K, float, void>& f, float v) {
    for (int i = 0; i < 16; ++i) for (int j = 0; j < 16; ++j) f.v[i][j] = v;
}
template <int M, int N, int K>
void store_matrix_sync(float* p, const fragment<accumulator, M, N, K, float, void>& f, unsigned ld, layout_t) {
    for (int i = 0; i < 16; ++i) for (int j = 0; j < 16; ++j) p[i * ld + j] = f.v[i][j];
}
template <class A, class B, class C>
void mma_sync(C& d, const A& a, const B& b, const C& c) {
    C r = c;
    for (int i = 0; i < 16; ++i) for (int j = 0; j < 16; ++j)
        for (int k = 0; k < 16; ++k) r.v[i][j] += a.v[i][k] * b.v[k][j];
    d = r;
}
} }
"#;

fn generate(tmp: &PathBuf, with_bias: bool) -> String {
    let bin = env!("CARGO_BIN_EXE_boring");
    let call = if with_bias {
        "kernel.tensors.linear(a, weights, bias, y, m = m, n = n, k = k, format = \"q8_0\")"
    } else {
        "kernel.tensors.linear(a, weights, y, m = m, n = n, k = k, format = \"q8_0\")"
    };
    let bias_param = if with_bias { "[float32]'kernel'global bias, " } else { "" };
    let src = format!(
        "req [float32]'kernel'unified compute([float32]'kernel'global a, [uint8]'kernel'global weights, {bias_param}int m, int n, int k) throws:\n    mut [float32]'kernel'unified y = [0.0 as float32 for ..<m * n]\n    {call}\n    y\n"
    );
    let _ = fs::remove_dir_all(tmp);
    fs::create_dir_all(tmp).unwrap();
    fs::write(tmp.join("test.br"), src).unwrap();
    fs::write(tmp.join("boring.toml"), "[tensor.linear.prefill]\nprecision = \"half\"\n").unwrap();
    let result = Command::new(bin).args(["build", "--target", "cuda"]).arg(tmp.join("test.br")).output().unwrap();
    assert!(result.status.success(), "{}", String::from_utf8_lossy(&result.stderr));
    fs::read_to_string(tmp.join("test_cuda/kernels/main.cu")).unwrap()
}

fn run_case(name: &str, with_bias: bool, m: usize, n: usize, k: usize) {
    let tmp = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("cuda_half_prefill_emulation").join(name);
    let cu = generate(&tmp, with_bias);
    assert!(cu.contains("nvcuda::wmma::mma_sync"), "half WMMA kernel expected:\n{cu}");
    let kernel = cu
        .lines()
        .find_map(|line| line.strip_prefix("__global__ void ").and_then(|rest| rest.split('(').next()))
        .expect("kernel entry point")
        .to_string();

    let inc = tmp.join("inc");
    fs::create_dir_all(&inc).unwrap();
    fs::write(inc.join("fake_cuda.h"), FAKE_CUDA_RUNTIME).unwrap();
    fs::write(inc.join("cuda_runtime.h"), "#include \"fake_cuda.h\"\n").unwrap();
    fs::write(inc.join("cuda_fp16.h"), "#include \"fake_cuda.h\"\n").unwrap();
    fs::write(inc.join("mma.h"), FAKE_MMA).unwrap();

    let bias_decl = if with_bias { "const float* bias_ptr = bias.data();" } else { "" };
    let bias_arg = if with_bias { "bias_ptr, " } else { "" };
    let bias_ref = if with_bias { "bias[c]" } else { "0.0f" };
    let harness = format!(
        r##"
#include "{cu_path}"
#include <cstdio>
#include <thread>
#include <vector>
int main() {{
    const int M = {m}, N = {n}, K = {k};
    std::vector<float> x(M * K), bias(N), y(M * N, -999.0f);
    for (int i = 0; i < M * K; ++i) x[i] = float(i % 17) / 7.0f - 1.0f;
    for (int i = 0; i < N; ++i) bias[i] = float(i) * 0.02f;
    std::vector<uint8_t> w((N * K / 32) * 34);
    auto q = [](long flat) {{ return int((flat * 7) % 23) - 11; }};
    for (size_t i = 0; i < w.size(); ++i) {{
        long block = i / 34, pos = i % 34;
        w[i] = pos == 0 ? 0x00 : pos == 1 ? 0x38 : uint8_t(int8_t(q(block * 32 + (pos - 2))));
    }}
    {bias_decl}
    blockDim = {{256, 1, 1}};
    gridDim = {{unsigned((N + 63) / 64), unsigned((M + 63) / 64), 1}};
    boring_barrier.count = 256;
    for (unsigned by = 0; by < gridDim.y; ++by) for (unsigned bx = 0; bx < gridDim.x; ++bx) {{
        blockIdx = {{bx, by, 0}};
        std::vector<std::thread> threads;
        for (unsigned t = 0; t < 256; ++t) threads.emplace_back([&, t] {{
            threadIdx = {{t, 0, 0}};
            {kernel}(x.data(), w.data(), {bias_arg}y.data(), M, N, K);
        }});
        for (auto& th : threads) th.join();
    }}
    double worst = 0, scale = 0;
    for (int r = 0; r < M; ++r) for (int c = 0; c < N; ++c) {{
        float expected = {bias_ref};
        for (int i = 0; i < K; ++i) expected += __float2half(x[r * K + i]) * __float2half(float(q(long(c) * K + i)) * 0.5f);
        worst = std::fmax(worst, std::fabs(y[r * N + c] - expected));
        scale = std::fmax(scale, std::fabs(expected));
    }}
    std::printf("max abs error %g (max |y| %g)\n", worst, scale);
    // The reference applies the same half rounding, so only fp32 summation order may differ.
    return worst <= 2e-4 ? 0 : 1;
}}
"##,
        cu_path = tmp.join("test_cuda/kernels/main.cu").display(),
    );
    fs::write(tmp.join("harness.cpp"), harness).unwrap();
    let binary = tmp.join("harness");
    let compile = Command::new("c++")
        .args(["-std=c++17", "-O1", "-pthread", "-x", "c++", "-I"]).arg(&inc)
        .arg(tmp.join("harness.cpp")).arg("-o").arg(&binary)
        .output().expect("a C++ compiler is required for the emulation test");
    assert!(compile.status.success(), "{}", String::from_utf8_lossy(&compile.stderr));
    let run = Command::new(&binary).output().unwrap();
    assert!(
        run.status.success(),
        "half prefill kernel disagrees with the reference: {}",
        String::from_utf8_lossy(&run.stdout)
    );
}

#[test]
#[cfg(unix)]
fn half_wmma_prefill_matches_half_rounded_reference_with_bias_and_edge_tiles() {
    // m and n are not multiples of 64 (edge tiles); k spans several 16-deep stages.
    run_case("bias_edges", true, 70, 96, 96);
}

#[test]
#[cfg(unix)]
fn half_wmma_prefill_matches_reference_without_bias_on_a_single_partial_tile() {
    run_case("no_bias_small", false, 5, 19, 64);
}
